[E("conceptual","Explain the Spring MVC request flow.","DispatcherServlet, HandlerMapping, Controller, ViewResolver, View."),
 E("explain with example","Write a simple Spring MVC controller.","@Controller with @GetMapping returning view name and Model attribute.")],
[Q("MCQ","Front controller:","DispatcherServlet","",["HandlerMapping","DispatcherServlet","ViewResolver","Model"]),
 Q("true/false","ViewResolver maps logical names to views.","True",""),
 Q("short answer","Annotation for a controller class?","@Controller",""),
 Q("scenario","Read query parameter id. Use?","@RequestParam",""),
 Q("comparison","@Controller vs @RestController.","@Controller returns views; @RestController returns response body (JSON).","")],
"Spring MVC: DispatcherServlet → HandlerMapping → Controller → ModelAndView → ViewResolver → View.",
syntax="@Controller public class HelloController { @GetMapping(\"/hello\") public String hello(Model m){ … return \"hello\"; } }",
code="@Controller\npublic class HelloController {\n  @GetMapping(\"/hello\")\n  public String hello(@RequestParam(defaultValue = \"Guest\") String name, Model model) {\n    model.addAttribute(\"msg\", \"Hello \" + name);\n    return \"hello\";   // /WEB-INF/views/hello.jsp\n  }\n}",
expectedOutput="GET /hello?name=Asha → page showing Hello Asha",
